// Beverages report (31 Jan 2023), §6.6.2: 4 unfavourable points for non-nutritive sweeteners.
// SpF's updated-algorithm calculator (20240404), "Non-nutritive sweeteners", and FAQ V11,
// Appendix 3, also include newly authorized NNS (E960c/d: 2021/1156 and 2023/447;
// E960b: 2025/652). The points algorithm remains the 2023 version.
// Polyols and E956 remain excluded. See data/SCORE-VALIDATION.md for the primary references.
const E_NUMBERS = /\be[\s-]?(950|951|952|954|955|957|959|960[a-d]?|961|962|969)\b/;
// Romanian label names, without diacritics. A human still has to check them against the RO text of
// Reg. (CE) nr. 1333/2008, Anexa II; the E-numbers above are the authoritative match.
const NAMES = /acesulfam|aspartam|ciclamat|zaharina|sucraloza|taumatina|neohesperidina|neotam|advantam/;
// All authorized steviol glycosides count, irrespective of their production method.
const STEVIA = /steviol|\bstevia\b/;

export function hasNonNutritiveSweetener(ingredientsText: string): boolean {
  const plain = ingredientsText.toLowerCase().normalize('NFD').replace(/\p{M}/gu, '');
  return E_NUMBERS.test(plain) || NAMES.test(plain) || STEVIA.test(plain);
}
